      description:
        '巴掌大的复合卡片，正面是照片、姓名、职级、部门与工号，背面是一层磨砂涂层。它同时是身份证、钱包、考勤卡与定位器：每一次刷闸机都会留下层号、时间与闸机编号，每一次配给领取都会进入个人档案，每一次跨层移动都会在纪律监察部的日志里形成条目，记录保留七年。工牌断电即失效，失效即意味着你在制度上不再是集团的人。地渊人有一句话：你可以丢掉工作，不能丢掉工牌。',
